function userCategoryText(u) {
  return []
    .concat(u?.category || [])
    .concat(u?.niches || [])
    .concat(u?.industry || [])
    .flatMap((x) => (Array.isArray(x) ? x : String(x).split(",")))
    .map((x) => String(x).trim())
    .filter(Boolean)
    .join(", ");
}

function userMatchesCategories(u, selected = []) {
  if (!selected?.length) return true;
  const cats = []
    .concat(u?.category || [])
    .concat(u?.niches || [])
    .concat(u?.industry || []);
  return matchesCategoryFilter(cats, selected);
}
